INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-telling-time', 'A1', 'Telling Time (Mis kell on?)', 'Saat Söyleme (Mis kell on?)', '<b>Telling Time in Estonian</b>\n\n<b>Full hours:</b>\nKell on <code>üks</code>. — It is 1 o''clock.\nKell on <code>kaks</code>. — It is 2 o''clock.\n\n<b>Half hours (pool = half BEFORE next hour):</b>\n6:30 = <code>pool seitse</code> (half before seven)\n12:30 = <code>pool üks</code> (half before one)\n8:30 = <code>pool üheksa</code> (half before nine)\n\n<b>Quarter past (veerand):</b>\n1:15 = <code>veerand kaks</code> (quarter of two)\n3:15 = <code>veerand neli</code> (quarter of four)\n\n<b>Quarter to (kolmveerand):</b>\n1:45 = <code>kolmveerand kaks</code> (three-quarters of two)\n5:45 = <code>kolmveerand kuus</code> (three-quarters of six)\n\n<i>Remember: Estonian counts toward the NEXT hour!</i>', '<b>Estoncada Saat Söyleme</b>\n\n<b>Tam saatler:</b>\nKell on <code>üks</code>. — Saat 1.\nKell on <code>kaks</code>. — Saat 2.\n\n<b>Buçuklar (pool = sonraki saatin yarısı):</b>\n6:30 = <code>pool seitse</code> (yedinin yarısı)\n12:30 = <code>pool üks</code> (birin yarısı)\n\n<b>Çeyrek geçe (veerand):</b>\n1:15 = <code>veerand kaks</code> (ikinin çeyreği)\n\n<b>Çeyrek kala (kolmveerand):</b>\n1:45 = <code>kolmveerand kaks</code> (ikinin üç çeyreği)\n\n<i>Dikkat: Estonca sonraki saate göre sayar!</i>') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-clothing-locations', 'A1', 'Clothing Grammar (Where is it worn?)', 'Kıyafet Grameri (Nereye giyilir?)', '<b>Where Clothing is Worn</b>\n\n<code>peas</code> (on the head): müts, kiiver, kapuuts\n<code>kaelas</code> (around the neck): sall, lips, kaelakee\n<code>seljas</code> (on the back/torso): särk, kampsun, jope\n<code>jalas</code> (on legs/feet): püksid, saapad, sokid\n<code>käes</code> (in the hands): kindad, vihmavari, kott\n<code>ees</code> (on the face): prillid, päikeseprillid, mask\n\n💬 <i>Tal on müts <code>peas</code>.</i> — He has a hat on.\n💬 <i>Tal on jope <code>seljas</code>.</i> — He has a jacket on.\n💬 <i>Tal on prillid <code>ees</code>.</i> — He has glasses on.', '<b>Kıyafetler Nereye Giyilir?</b>\n\n<code>peas</code> (başta): müts, kiiver, kapuuts\n<code>kaelas</code> (boyunda): sall, lips, kaelakee\n<code>seljas</code> (sırtta): särk, kampsun, jope\n<code>jalas</code> (bacaklarda): püksid, saapad, sokid\n<code>käes</code> (ellerde): kindad, vihmavari, kott\n<code>ees</code> (yüzde): prillid, päikeseprillid, mask\n\n💬 <i>Tal on müts <code>peas</code>.</i> — Şapkası var.\n💬 <i>Tal on jope <code>seljas</code>.</i> — Montu var.\n💬 <i>Tal on prillid <code>ees</code>.</i> — Gözlüğü var.') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-comitative-abessive', 'A1', 'With (-ga) & Without (-ta)', 'İle (-ga) ve Sız/Siz (-ta)', '<b>Comitative -ga (with) & Abessive -ta (without)</b>\n\nAdd to the Genitive form:\n\n<b>-ga (with):</b>\nauto → auto<code>ga</code> (by car)\npiim → piima<code>ga</code> (with milk)\nsina → sinu<code>ga</code> (with you)\n\n💬 <i>Ma joon kohvi <code>piimaga</code>.</i> — I drink coffee with milk.\n💬 <i>Ma sõidan <code>autoga</code>.</i> — I travel by car.\n\n<b>-ta (without):</b>\nauto → auto<code>ta</code> (without car)\nsuhkur → suhkru<code>ta</code> (without sugar)\n\n💬 <i>Kohv <code>suhkruta</code>, palun.</i> — Coffee without sugar, please.', '<b>-ga (ile) ve -ta (sız/siz)</b>\n\nİsmin tamlayan haline eklenir:\n\n<b>-ga (ile):</b>\nauto → auto<code>ga</code> (arabayla)\npiim → piima<code>ga</code> (sütle)\nsina → sinu<code>ga</code> (seninle)\n\n💬 <i>Ma joon kohvi <code>piimaga</code>.</i> — Kahveyi sütle içerim.\n\n<b>-ta (sız/siz):</b>\nsuhkur → suhkru<code>ta</code> (şekersiz)\n\n💬 <i>Kohv <code>suhkruta</code>, palun.</i> — Şekersiz kahve, lütfen.') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-ma-da-infinitive', 'A1', 'MA vs DA Infinitive', 'MA ve DA Mastar Sistemi', '<b>Two Infinitive Forms</b>\n\n<b>MA-infinitive</b> — after movement/obligation verbs:\n💬 <i>Ma lähen <code>õppima</code>.</i> — I go to study.\n💬 <i>Ma hakkan <code>töötama</code>.</i> — I start working.\n\n<b>DA-infinitive</b> — after desire/feeling/ability verbs:\n💬 <i>Ma tahan <code>õppida</code>.</i> — I want to study.\n💬 <i>Mulle meeldib <code>tantsida</code>.</i> — I like to dance.\n💬 <i>Ma oskan <code>ujuda</code>.</i> — I can swim.\n\n<b>Quick pairs:</b>\njooma/juua (drink), sööma/süüa (eat), õppima/õppida (study), minema/minna (go)', '<b>İki Mastar Formu</b>\n\n<b>MA-mastar</b> — hareket/zorunluluk fiillerinden sonra:\n💬 <i>Ma lähen <code>õppima</code>.</i> — Çalışmaya gidiyorum.\n💬 <i>Ma hakkan <code>töötama</code>.</i> — Çalışmaya başlıyorum.\n\n<b>DA-mastar</b> — istek/duygu/yetenek fiillerinden sonra:\n💬 <i>Ma tahan <code>õppida</code>.</i> — Çalışmak istiyorum.\n💬 <i>Mulle meeldib <code>tantsida</code>.</i> — Dans etmeyi severim.\n\n<b>Hızlı çiftler:</b>\njooma/juua (içmek), sööma/süüa (yemek), õppima/õppida (çalışmak), minema/minna (gitmek)') ON CONFLICT (id) DO NOTHING;
